"""
Русский язык для IT — skill tests per module (quiz, 4 options).
Tasks/options in Russian; titles/descriptions can be Uzbek for UI.
"""


def _q(num: int, title: str, task: str, options: list[str], answer: str, editorial: str, difficulty: str = "easy"):
    assert answer in "ABCD"
    assert len(options) == 4
    return {
        "num": num,
        "title": title,
        "description": "Modul bilim testi. To‘g‘ri ruscha javobni tanlang.",
        "task": task,
        "kind": "quiz",
        "difficulty": difficulty,
        "is_skill_test": True,
        "quiz_options": options,
        "hints": [
            "Darsdagi IT so‘zlarini eslang.",
            "Noto‘g‘ri variantlarni chiqarib tashlang.",
        ],
        "editorial": editorial,
        "columns": ["javob"],
        "rows": [[answer]],
    }


